        <style>
            body,
            .content {
                margin: 0;
            }

            .ballot {
                display: flex;
                justify-content: center;
                align-items: flex-start;
                overflow: hidden;
                box-sizing: border-box;
            }

            .inner-ballot {
                border: 16px solid transparent;
                border-image: url('{{file_qrcode_lib}}/../ballot-background.jpg');

                /* width: 8 Container width */

                border-image-slice: 25 fill;
                /*Adjust slice values for your design*/
                /* border-image-width: 6%; */
                /* border-image-repeat: stretch; Stretches border */

                /* transform-origin: top left; */
                /* transform: scale(0.8); */
                height: 100%;
                /* height:max-content; */
                page-break-inside: avoid;
                padding: 20px;
                width: 900px;
            }

            .ballot-data {
                height: 29in;
                display: flex;
                flex-direction: column;
                width: 900px;
                transform: scale(0.94);
            }

            @media print {

                html,
                body,
                .content {
                    height: 100%;
                }

                .ballot {
                    height: 100%;
                    width: 900px;
                    overflow-y: hidden;
                }

                .summary-page {
                    height: 100%;
                    width: 900px;
                    overflow-y: hidden;
                    text-align: center;
                }

                .inner-ballot {
                    page-break-before: avoid;
                    page-break-after: avoid;
                    width: 900px;
                    transform-origin: top center;
                    transform: scale(0.47);
                }
            }

            .header {
                display: flex;
                justify-content: space-between;
                font-size: 12px;
                position: relative;
                height: 295px;
            }

            .header .left {
                text-align: left;
                flex: 1;
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                justify-content: space-between;
                height: 300px;
            }

            .image-url {
                width: 100px;
            }

            .header .center {
                text-align: center;
                flex: 1;
            }

            .header .right {
                position: absolute;
                top: 0;
                right: 0;
                text-align: right;
                display: flex;
                flex-direction: column;
                align-items: flex-end;
                justify-content: space-between;
                gap: 35px;
            }

            .header h2 {
                font-size: 16px;
                margin: 20px 0 0 0;
            }

            .header p {
                margin: 2px 0;
                font-size: 12px;
            }

            .header ol {
                margin: 0;
                font-size: 14px;
                padding-inline-start: 18px;
                display: flex;
                flex-direction: column;
                gap: 4px;
            }

            .header .instructions-header {
                font-size: 16px;
            }

            .header .election-name {
                font-weight: bold;
                text-transform: uppercase;
            }

            .header .qr-code {
                flex: 1
            }

            .header .qr-code img {
                width: 165px;
            }

            .header img {
                width: 240px;
            }

            .election-info {
                font-size: 18px !important;
            }

            .instruction {
                display: flex;
                align-items: center;
            }


            .header .signature {
                display: block;
                float: right;
                border: 1px solid black;
                text-align: center;
                vertical-align: bottom;
                width: 250px;
                height: 50px;
                margin-top: 10px;
                display: flex;
                align-items: end;
                justify-content: center;
            }

            .ballot-content {
                margin-top: 20px;
                font-size: 10px;
                flex: 1;
            }

            .section {}

            .section-title {
                border: 1px solid black;
                background-color: #007bff;
                color: white;
                padding: 10px;
                text-align: center;
            }

            .section-title.green {
                background-color: #d1e3d1;
                color: black
            }

            .section-title.blue {
                background-color: #007bff;
            }

            .candidates {
                display: block;
                columns: 4;
                column-count: 4;
                -webkit-column-count: 4;
                -moz-column-count: 4;
                column-gap: 0;
                width: 100%;
            }

            .candidate {
                border: 1px solid black;
                box-sizing: border-box;
                width: 100%;
                padding: 2px;
                height: 32px;
                display: inline-block;
            }

            .candidate div {
                display: flex;
                align-items: center;
            }

            .circle {
                display: block;
                position: relative;
                width: 94px;
                height: auto;
            }

            .is-blank,
            .is-invalid {
                padding: 5px 0 5px 5px;
                box-sizing: border-box;
                display: flex;
                align-items: center;
            }

            .is-blank .candidate-name,
            .is-invalid .candidate-name {
                margin-right: 10px;
            }

            .is-blank input[type="checkbox"],
            .is-invalid input[type="checkbox"] {
                margin-right: 0;
            }

            input[type="checkbox"] {
